from taf.collectors.journal.collector import JournalCollector
from taf.collectors.core.factories.factory import Factory
from taf.collectors.core.factories.collector_factory import RemoteCommandCollectorFactory, LocalCommandCollectorFactory

import logging

logger = logging.getLogger(__name__)
logger.addHandler(logging.NullHandler())


class JournalCollectorFactory(object):
    """
        factory to create journal collectors
    """

    def create(self, configuration, existing_arguments):
        """

        Create a JournalCollector.

        :param dict configuration:
                collection of configuration parameters for the object to be created and other objects,
                that might have to be created as prerequisites
        :param dict existing_arguments:
                existing arguments for the final constructor call, that don't need to be created
                (dict with constructor parameter name as key and argument value as value)


        :return: JournalCollector
        """
        resulting_arguments = {}
        self._build_arguments(configuration=configuration,
                              existing_arguments=existing_arguments,
                              resulting_arguments=resulting_arguments)
        return JournalCollector(**resulting_arguments)

    def _build_arguments(self, configuration, existing_arguments, resulting_arguments):
        super(JournalCollectorFactory, self)._build_arguments(
            configuration=configuration,
            existing_arguments=existing_arguments,
            resulting_arguments=resulting_arguments)
        if "options" in configuration:
            resulting_arguments["options"] = configuration["options"]
        if "journal_path" in configuration:
            resulting_arguments["journal_path"] = configuration["journal_path"]
        if "target_file_name" in configuration:
            resulting_arguments["target_file_name"] = configuration["target_file_name"]


class RemoteJournalCollectorFactory(JournalCollectorFactory, RemoteCommandCollectorFactory):
    pass


class LocalJournalCollectorFactory(JournalCollectorFactory, LocalCommandCollectorFactory):
    pass


class JournalCollectorFactorySelector(Factory):

    def create(self, configuration, existing_arguments):
        if "executor" in configuration:
            return RemoteJournalCollectorFactory().create(configuration=configuration,
                                                          existing_arguments=existing_arguments)
        else:
            return LocalJournalCollectorFactory().create(configuration=configuration,
                                                         existing_arguments=existing_arguments)
